    app.innerHTML=`<main class="login-page"><div class="login-art" aria-hidden="true"></div><section class="login-form-card"><h1 class="login-title">账号登录</h1><p class="login-sub">进入声学超材料研发平台</p><div class="login-tabs"><button class="login-tab active" data-login-tab="password">密码登录</button><button class="login-tab" data-login-tab="code">验证码登录</button></div><form id="login-form"><div id="login-fields" class="stack" style="gap:13px"><div class="field"><label>账号 / 手机号</label><input class="input" name="account" value="admin" autocomplete="username" placeholder="请输入账号或手机号"></div><div class="field"><label>密码</label><div class="password-wrap"><input class="input" type="password" name="password" value="123456" autocomplete="current-password" placeholder="请输入密码"><button type="button" class="text-btn" data-action="toggle-password">显示</button></div></div></div><div class="login-options"><label class="check"><input type="checkbox" name="remember">记住登录（7 天）</label><button type="button" class="text-btn" data-action="forgot">忘记密码？</button></div><button class="btn btn-primary login-primary" type="submit">登 录</button></form><div class="login-footer">还没有账号？<button class="text-btn" data-action="register">注册</button></div><div class="demo-box"><b>原型体验账号</b><br>管理员：admin / 123456　普通用户：user / 123456<br>待审核用户：pending / 123456（可体验权限拦截）</div></section></main>`;
    bindLogin();
