  function bindLogin(){
    let mode='password';
    $$('[data-login-tab]').forEach(b=>b.addEventListener('click',()=>{
      mode=b.dataset.loginTab; $$('[data-login-tab]').forEach(x=>x.classList.toggle('active',x===b));
      $('#login-fields').innerHTML= mode==='password'?`<div class="field"><label>账号 / 手机号</label><input class="input" name="account" value="admin" placeholder="请输入账号或手机号"></div><div class="field"><label>密码</label><div class="password-wrap"><input class="input" type="password" name="password" value="123456" placeholder="请输入密码"><button type="button" class="text-btn" data-action="toggle-password">显示</button></div></div>`:`<div class="field"><label>手机号</label><input class="input" name="account" value="13800000000" placeholder="请输入手机号"></div><div class="field"><label>验证码</label><div class="code-row"><input class="input" name="code" value="888888" placeholder="请输入验证码"><button type="button" class="btn" data-action="send-code">获取验证码</button></div></div>`;
    }));
    $('#login-form')?.addEventListener('submit',e=>{
      e.preventDefault(); const fd=new FormData(e.currentTarget); const acc=String(fd.get('account')||'').trim();
      const u=state.users.find(x=>x.account===acc||x.phone===acc);
      if(!u){toast('登录失败','当前不存在用户信息，需重新注册','error');return;}
      if(mode==='password' && fd.get('password')!==u.password){toast('登录失败','密码错误','error');return;}
      if(mode==='code' && fd.get('code')!=='888888'){toast('登录失败','验证码错误（原型验证码：888888）','error');return;}
      state.session={id:u.id,name:u.name,role:u.role,status:u.status,unit:u.unit,remember:!!fd.get('remember')}; saveState(); addLog('登录','用户登录成功');
      if(u.status==='pending') toast('账号待审核','当前账号可登录浏览，但功能操作需审核后使用','warn',4500); else toast('登录成功',`欢迎，${u.name}`);
      go('home');
    });
  }

